def handle(app, svc):
    result = svc.apply(app)
    decision = result.get("decision")
    limit = result.get("limit", 0)

    if decision == "decline":
        return {"action": "decline", "limit": 0}

    if decision == "refer":
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 7000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}

    # Unknown decision: be safe and route to manual review.
    return {"action": "queue_review", "limit": 0}

